-- Amigo Fiel Pet Shop | MySQL 8.0
CREATE DATABASE IF NOT EXISTS amigo_fiel_petshop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE amigo_fiel_petshop;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `auditoria_cancelamento`;
DROP TABLE IF EXISTS `movimentacao_estoque`;
DROP TABLE IF EXISTS `pagamento`;
DROP TABLE IF EXISTS `item_venda`;
DROP TABLE IF EXISTS `venda`;
DROP TABLE IF EXISTS `produto_fornecedor`;
DROP TABLE IF EXISTS `fornecedor`;
DROP TABLE IF EXISTS `produto`;
DROP TABLE IF EXISTS `atendimento`;
DROP TABLE IF EXISTS `agendamento`;
DROP TABLE IF EXISTS `servico`;
DROP TABLE IF EXISTS `funcionario`;
DROP TABLE IF EXISTS `animal`;
DROP TABLE IF EXISTS `cliente`;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE cliente (id_cliente INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL, cpf VARCHAR(255) UNIQUE, telefone VARCHAR(255), email VARCHAR(255), data_cadastro DATE NOT NULL DEFAULT (CURRENT_DATE), status VARCHAR(255) NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','inativo'))) ENGINE=InnoDB;
CREATE TABLE animal (id_animal INT AUTO_INCREMENT PRIMARY KEY, id_cliente INT NOT NULL, nome VARCHAR(255) NOT NULL, especie VARCHAR(255) NOT NULL, raca VARCHAR(255), porte VARCHAR(255), data_nascimento DATE, observacoes VARCHAR(255), FOREIGN KEY (id_cliente) REFERENCES cliente(id_cliente)) ENGINE=InnoDB;
CREATE TABLE funcionario (id_funcionario INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL, cpf VARCHAR(255) UNIQUE, cargo VARCHAR(255) NOT NULL, telefone VARCHAR(255), status VARCHAR(255) NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','inativo'))) ENGINE=InnoDB;
CREATE TABLE servico (id_servico INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL UNIQUE, descricao VARCHAR(255), preco_base DECIMAL(12,2) NOT NULL CHECK(preco_base>=0), duracao_minutos INT NOT NULL CHECK(duracao_minutos>0), status VARCHAR(255) NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','inativo'))) ENGINE=InnoDB;
CREATE TABLE agendamento (id_agendamento INT AUTO_INCREMENT PRIMARY KEY, id_animal INT NOT NULL, id_servico INT NOT NULL, id_funcionario INT NOT NULL, inicio DATETIME NOT NULL, fim DATETIME NOT NULL, status VARCHAR(255) NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','confirmado','em_atendimento','concluido','cancelado')), observacoes VARCHAR(255), CHECK(fim>inicio), FOREIGN KEY (id_animal) REFERENCES animal(id_animal), FOREIGN KEY (id_servico) REFERENCES servico(id_servico), FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario)) ENGINE=InnoDB;
CREATE TABLE atendimento (id_atendimento INT AUTO_INCREMENT PRIMARY KEY, id_agendamento INT NOT NULL UNIQUE, FOREIGN KEY (id_agendamento) REFERENCES agendamento(id_agendamento), id_funcionario INT NOT NULL, inicio DATETIME NOT NULL, fim DATETIME, observacoes VARCHAR(255), valor_final DECIMAL(12,2) NOT NULL CHECK(valor_final>=0), status VARCHAR(255) NOT NULL DEFAULT 'em_andamento' CHECK(status IN ('em_andamento','concluido')), CHECK(fim IS NULL OR fim>=inicio), FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario)) ENGINE=InnoDB;
CREATE TABLE produto (id_produto INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL, categoria VARCHAR(255) NOT NULL, preco_venda DECIMAL(12,2) NOT NULL CHECK(preco_venda>=0), estoque_atual INT NOT NULL DEFAULT 0 CHECK(estoque_atual>=0), estoque_minimo INT NOT NULL DEFAULT 0 CHECK(estoque_minimo>=0), status VARCHAR(255) NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','inativo'))) ENGINE=InnoDB;
CREATE TABLE fornecedor (id_fornecedor INT AUTO_INCREMENT PRIMARY KEY, razao_social VARCHAR(255) NOT NULL, nome_fantasia VARCHAR(255), cnpj VARCHAR(255) NOT NULL UNIQUE, telefone VARCHAR(255), email VARCHAR(255), status VARCHAR(255) NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','inativo'))) ENGINE=InnoDB;
CREATE TABLE produto_fornecedor (id_produto INT NOT NULL, id_fornecedor INT NOT NULL, preco_compra DECIMAL(12,2) NOT NULL CHECK(preco_compra>=0), prazo_entrega_dias INT CHECK(prazo_entrega_dias>=0), codigo_fornecedor VARCHAR(255), PRIMARY KEY(id_produto,id_fornecedor), FOREIGN KEY (id_produto) REFERENCES produto(id_produto), FOREIGN KEY (id_fornecedor) REFERENCES fornecedor(id_fornecedor)) ENGINE=InnoDB;
CREATE TABLE venda (id_venda INT AUTO_INCREMENT PRIMARY KEY, id_cliente INT, id_funcionario INT NOT NULL, data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, desconto DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(desconto>=0), autorizada_por INT, valor_total DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(valor_total>=0), status VARCHAR(255) NOT NULL DEFAULT 'aberta' CHECK(status IN ('aberta','concluida','cancelada')), data_cancelamento DATETIME, motivo_cancelamento VARCHAR(255), cancelada_por INT, FOREIGN KEY (id_cliente) REFERENCES cliente(id_cliente), FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario), FOREIGN KEY (autorizada_por) REFERENCES funcionario(id_funcionario), FOREIGN KEY (cancelada_por) REFERENCES funcionario(id_funcionario)) ENGINE=InnoDB;
CREATE TABLE item_venda (id_item INT AUTO_INCREMENT PRIMARY KEY, id_venda INT NOT NULL, id_produto INT NOT NULL, quantidade INT NOT NULL CHECK(quantidade>0), preco_unitario DECIMAL(12,2) NOT NULL CHECK(preco_unitario>=0), subtotal DECIMAL(12,2) GENERATED ALWAYS AS (quantidade*preco_unitario) STORED, UNIQUE(id_venda,id_produto), FOREIGN KEY (id_venda) REFERENCES venda(id_venda), FOREIGN KEY (id_produto) REFERENCES produto(id_produto)) ENGINE=InnoDB;
CREATE TABLE pagamento (id_pagamento INT AUTO_INCREMENT PRIMARY KEY, id_venda INT, id_atendimento INT, data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, forma VARCHAR(255) NOT NULL CHECK(forma IN ('pix','dinheiro','debito','credito','transferencia')), valor DECIMAL(12,2) NOT NULL CHECK(valor>0), status VARCHAR(255) NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','aprovado','estornado','cancelado')), CHECK ((id_venda IS NOT NULL AND id_atendimento IS NULL) OR (id_venda IS NULL AND id_atendimento IS NOT NULL)), FOREIGN KEY (id_venda) REFERENCES venda(id_venda), FOREIGN KEY (id_atendimento) REFERENCES atendimento(id_atendimento)) ENGINE=InnoDB;
CREATE TABLE movimentacao_estoque (id_movimentacao INT AUTO_INCREMENT PRIMARY KEY, id_produto INT NOT NULL, id_venda INT, id_funcionario INT NOT NULL, data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, tipo VARCHAR(255) NOT NULL CHECK(tipo IN ('entrada','saida','ajuste_entrada','ajuste_saida','estorno')), quantidade INT NOT NULL CHECK(quantidade>0), motivo VARCHAR(255) NOT NULL, FOREIGN KEY (id_produto) REFERENCES produto(id_produto), FOREIGN KEY (id_venda) REFERENCES venda(id_venda), FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario)) ENGINE=InnoDB;
CREATE TABLE auditoria_cancelamento (id_auditoria INT AUTO_INCREMENT PRIMARY KEY, id_venda INT NOT NULL, data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, id_funcionario INT NOT NULL, motivo VARCHAR(255) NOT NULL, FOREIGN KEY (id_venda) REFERENCES venda(id_venda), FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario)) ENGINE=InnoDB;
CREATE INDEX idx_animal_cliente ON animal(id_cliente);
CREATE INDEX idx_agendamento_funcionario_inicio ON agendamento(id_funcionario,inicio,fim);
CREATE INDEX idx_item_venda ON item_venda(id_venda);
CREATE INDEX idx_pagamento_venda ON pagamento(id_venda);
CREATE INDEX idx_movimentacao_produto ON movimentacao_estoque(id_produto);
